    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which state of matter is most likely to be found in stars due to extremely high temperatures?', '["Solid","Plasma","Liquid","Bose-Einstein Condensate"]'::jsonb, 'B', 1, '9e6ad89174c2', null),
