    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is a suspension considered a heterogeneous mixture?', '["Because its components are chemically bonded","Because its components are not uniformly distributed and can be separated","Because it is invisible to the naked eye","Because it is a pure substance"]'::jsonb, 'B', 1, '5c1c3dc6fa12', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which property of liquids allows them to take the shape of their container?', '["High density","Fluidity","Compressibility","Rigid structure"]'::jsonb, 'B', 1, '65e6a8ee7801', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A liquid changes into a gas when:', '["Particle motion decreases","Chemical bonds are permanently broken","New substances are formed","Particles gain sufficient energy to escape"]'::jsonb, 'D', 1, '9610a6aa0322', null),
